// Concatenates the shared engine + the entry point into a single Office Script file.
const fs = require('fs'), path = require('path');
const root = path.join(__dirname, '..');
const engine = fs.readFileSync(path.join(root, 'src/engine.ts'), 'utf8');
const main = fs.readFileSync(path.join(root, 'automation/office_script_main.ts'), 'utf8');
const header = '// RunQualityChecks - Office Script (Excel > Automate > New Script, paste, save as "RunQualityChecks")\n' +
  '// GENERATED by src/build_office_script.js from src/engine.ts + automation/office_script_main.ts - edit those, then rebuild.\n\n';
fs.writeFileSync(path.join(root, 'automation/RunQualityChecks.ts'), header + main.replace(/^\n/, '') + '\n' + engine);
console.log('Office Script written');
